INSERT INTO questions (id, content, difficulty, sub_category_id) VALUES
('b0000000-0000-0000-0010-000000000000', 'PostgreSQL은 무엇이며 다른 SQL DB와 어떤 차별점이 있나요?', 'EASY', 'b0000000-0000-0000-0000-000000000010'),
('b0000000-0000-0000-0010-000000000001', 'PostgreSQL의 대표적인 특징이나 장점은 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000010'),
('b0000000-0000-0000-0010-000000000002', 'PostgreSQL에서 JSON 데이터를 다루는 기능은 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000010'),
('b0000000-0000-0000-0010-000000000003', 'MVCC(Multi-Version Concurrency Control)란 무엇이며 PostgreSQL에서 어떻게 구현되나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000010'),
('b0000000-0000-0000-0010-000000000004', '트랜잭션 격리 수준(Transaction Isolation Level)은 PostgreSQL에서 어떻게 지원되나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000010'),
('b0000000-0000-0000-0010-000000000005', 'VACUUM 명령은 무엇이며 왜 필요합니까?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000010'),
('b0000000-0000-0000-0010-000000000006', 'ANALYZE 명령은 어떤 목적을 가지고 있나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000010'),
('b0000000-0000-0000-0010-000000000007', '시퀀스(Sequence)란 무엇이며, 자동 증가 값을 어떻게 생성하나요?', 'EASY', 'b0000000-0000-0000-0000-000000000010'),
('b0000000-0000-0000-0010-000000000008', 'PostgreSQL에서 서브쿼리와 조인 중 어느 것이 성능에 유리한가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000010'),
('b0000000-0000-0000-0010-000000000009', '윈도 함수(Window Function)란 무엇이고, 활용 예를 들어보세요.', 'HARD', 'b0000000-0000-0000-0000-000000000010'),
('b0000000-0000-0000-0010-00000000000A', 'CTE(Common Table Expression)란 무엇이며 언제 사용하나요?', 'HARD', 'b0000000-0000-0000-0000-000000000010'),
('b0000000-0000-0000-0010-00000000000B', '분산 환경에서 PostgreSQL을 확장하기 위한 방법은 무엇인가요?', 'HARD', 'b0000000-0000-0000-0000-000000000010');
